Procedure Hanoi (X, Y, Z: char; N: integer); 
Begin 
 If N>0 then  
    Begin 
       Hanoi (X, Z, Y, N-1); 
       Writeln('Disk ', N, ' from ', X, ' to ', Y); 
       Hanoi (Z, Y, X, N-1) 
    End 
End;

